parameters.functionScript:
switch (Inputs.buttonType) {
    case "bold":
        Outputs.bold();
        break;
    case "italics":
        Outputs.italics();
        break;
}

const editor = Inputs.Editor || null;
const functionName = Inputs.functionName;

if (!editor) throw new Error('Invalid Editor');

const functionLookup = {
  toggleBold: function() {
    editor.chain().focus().toggleBold().run();
  },
  toggleItalics: function() {
    editor.chain().focus().toggleItalic().run();
  },
  // ... add other functions as needed
};

try {
  if (functionLookup[functionName]) {
    functionLookup[functionName]();
    Outputs.Success();
  } else {
    throw new Error('Invalid function name');
  }
} catch (error) {
  Outputs.error = error;
  Outputs.Failure();
}
